package packet; import java.util.HashSet;import java.util.List;import java.util.Set; public final class PacketStats{private final List<PacketMetadata> packets;public PacketStats(List<PacketMetadata> packets){this.packets=packets;}public int total(){return packets.size();}public int dnsQueryCount(){int n=0;for(PacketMetadata p:packets)n+=p.dnsNames().size();return n;}public int uniqueIpCount(){Set<String>s=new HashSet<>();for(PacketMetadata p:packets){if(p.sourceIp()!=null)s.add(p.sourceIp().toString());if(p.destinationIp()!=null)s.add(p.destinationIp().toString());}return s.size();}public int privateToPublicFlows(){int n=0;for(PacketMetadata p:packets)if(p.sourceIp()!=null&&p.destinationIp()!=null&&p.sourceIp().isPrivate()&&!p.destinationIp().isPrivate())n++;return n;}}
